<template><div class="scope-tree"><el-input v-model="keyword" clearable placeholder="搜索分类名称或编号" aria-label="搜索分类目录" /><button type="button" class="all-categories" :aria-pressed="!categoryId" @click="emit('select','')">全部分类</button><div class="scope-tree-scroll" tabindex="0" aria-label="分类目录滚动区域"><ul><li v-for="row in rows" :key="row.id" :style="{paddingLeft:`${row.depth*14}px`}"><button v-if="row.hasChildren" type="button" class="twist" :aria-label="`${row.expanded?'折叠':'展开'} ${row.name}`" :aria-expanded="row.expanded" @click="toggle(row.id)">{{row.expanded?'▾':'▸'}}</button><span v-else class="twist"></span><button type="button" class="node" :data-catalog-tree-category="row.id" :aria-pressed="categoryId===row.id" :title="`${categoryPathLabel(categories,row.id)}（${row.id}）`" @click="emit('select',row.id)">{{row.name}}</button></li></ul></div></div></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {categoryChain,categoryPathLabel,visibleCategoryRows} from '../../domain/categoryTree'
import type {Category} from '../../domain/types'
const props=defineProps<{categories:Category[];categoryId:string;expandedIds:string[]}>(),emit=defineEmits<{select:[id:string];expand:[ids:string[]]}>(),keyword=ref('')
watch(()=>props.categoryId,()=>{const expanded=new Set(props.expandedIds);for(const parent of categoryChain(props.categories,props.categoryId).slice(0,-1))expanded.add(parent.id);if(expanded.size!==props.expandedIds.length)emit('expand',[...expanded])},{immediate:true})
const rows=computed(()=>{const needle=keyword.value.trim().toLowerCase(),expanded=new Set(props.expandedIds),matched=new Set<string>();if(needle)for(const category of props.categories)if(`${category.name} ${category.id}`.toLowerCase().includes(needle))for(const parent of categoryChain(props.categories,category.id)){matched.add(parent.id);if(parent.id!==category.id)expanded.add(parent.id)}return visibleCategoryRows(props.categories,expanded,'').filter(row=>!needle||matched.has(row.id))})
function toggle(id:string){const expanded=new Set(props.expandedIds);if(expanded.has(id))expanded.delete(id);else expanded.add(id);emit('expand',[...expanded])}
</script>
<style scoped>.scope-tree{display:flex;flex-direction:column;gap:8px}.scope-tree-scroll{overflow:auto;max-height:60vh;min-height:100px}ul{list-style:none;margin:0;padding:0;width:max-content;min-width:100%}li{display:flex;align-items:center;min-height:30px}button{font:inherit;cursor:pointer;border:0;background:none;color:var(--el-text-color-regular)}.node{text-align:left;white-space:nowrap;padding:5px 4px}.twist{width:20px;flex:none}.all-categories{text-align:left;padding:6px 0}[aria-pressed=true]{color:var(--el-color-primary);font-weight:600}button:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:-2px}</style>
